<script setup>
import{ref,onMounted}from'vue';import{api,json}from'../api';import{Plus,Pencil,Power,Trash2}from'lucide-vue-next';import Modal from'../components/Modal.vue';import Toast from'../components/Toast.vue'
const rows=ref([]),type=ref(''),show=ref(false),form=ref({}),toast=ref('');async function load(){rows.value=await api(`/api/admin/category/page${type.value?'?type='+type.value:''}`)}function edit(row={type:'1',sort:0,status:1}){form.value={...row};show.value=true}function msg(s){toast.value=s;setTimeout(()=>toast.value='',2200)}async function save(){await api('/api/admin/category',{method:form.value.id?'PUT':'POST',body:json(form.value)});show.value=false;msg('Saved');load()}async function status(r){await api(`/api/admin/category/${r.id}/status/${r.status?0:1}`,{method:'PATCH'});load()}async function remove(r){if(!confirm(`Delete category "${r.name}"?`))return;await api(`/api/admin/category/${r.id}`,{method:'DELETE'});msg('Deleted');load()}onMounted(load)
</script>
<template><div class="page-head"><div><h1>Categories</h1><p>Manage display categories for dishes and set meals</p></div><button class="primary" @click="edit()"><Plus :size="18"/>Add Category</button></div><div class="filters"><select v-model="type" @change="load"><option value="">All Types</option><option value="1">Dish Category</option><option value="2">Set Meal Category</option></select></div><div class="table-wrap"><table><thead><tr><th>Category Name</th><th>Type</th><th>Sort</th><th>Status</th><th class="actions">Actions</th></tr></thead><tbody><tr v-for="r in rows"><td><strong>{{r.name}}</strong></td><td>{{r.type==='1'?'Dish':'Set Meal'}}</td><td>{{r.sort}}</td><td><span class="status" :class="r.status?'on':'off'">{{r.status?'Enabled':'Disabled'}}</span></td><td class="actions"><button title="Edit" @click="edit(r)"><Pencil/></button><button title="Toggle status" @click="status(r)"><Power/></button><button title="Delete" class="danger" @click="remove(r)"><Trash2/></button></td></tr></tbody></table></div><Modal v-if="show" :title="form.id?'Edit Category':'Add Category'" @close="show=false"><form class="form-grid" @submit.prevent="save"><label>Category Name<input v-model="form.name" required/></label><label>Type<select v-model="form.type"><option value="1">Dish Category</option><option value="2">Set Meal Category</option></select></label><label>Sort<input v-model.number="form.sort" type="number" min="0" required/></label><footer><button type="button" class="secondary" @click="show=false">Cancel</button><button class="primary">Save</button></footer></form></Modal><Toast :message="toast"/></template>
